# ---------- PDF-помощники ----------


class Pdf:
    def __init__(self) -> None:
        import pymupdf

        self.pymupdf = pymupdf
        self.doc = pymupdf.open()
        self.page = None
        self.y = 0.0

    def new_page(self) -> None:
        self.page = self.doc.new_page(width=595, height=842)
        self.page.insert_font(fontname="dj", fontfile=FONT)
        self.page.insert_font(fontname="djb", fontfile=FONT_BOLD)
        self.y = 60

    def text(self, s: str, size: float = 11, bold: bool = False, gap: float = 6) -> None:
        if self.page is None or self.y > 760:
            self.new_page()
        rect = self.pymupdf.Rect(60, self.y, 535, 800)
        rc = self.page.insert_textbox(
            rect, s, fontname="djb" if bold else "dj", fontsize=size, lineheight=1.25
        )
        used = rect.height - rc if rc >= 0 else rect.height
        self.y += used + gap
        if rc < 0:  # не поместилось — переносим на новую страницу целиком
            self.new_page()
            self.text(s, size, bold, gap)

    def table(self, rows: list[tuple[str, ...]], widths: list[float]) -> None:
        row_h = 20
        if self.page is None or self.y + row_h * len(rows) > 780:
            self.new_page()
        x0 = 60
        for r, row in enumerate(rows):
            y = self.y + r * row_h
            x = x0
            for c, val in enumerate(row):
                rect = self.pymupdf.Rect(x, y, x + widths[c], y + row_h)
                self.page.draw_rect(rect, color=(0, 0, 0), width=0.6)
                self.page.insert_textbox(
                    rect + (3, 4, -3, 0), val, fontname="djb" if r == 0 else "dj", fontsize=8
                )
                x += widths[c]
        self.y += row_h * len(rows) + 12

    def save(self, out: Path) -> None:
        self.doc.save(out)
        self.doc.close()


