def make_teo(out: Path) -> None:
    pdf = Pdf()
    pdf.new_page()
    pdf.text("ТЕХНИКО-ЭКОНОМИЧЕСКОЕ ОБОСНОВАНИЕ", 18, bold=True, gap=14)
    pdf.text(
        "Строительство мукомольного завода производственной мощностью 320 тонн в сутки", 14, bold=True, gap=20
    )
    pdf.text(
        "Заказчик: ТОО «Агро Инвест Кокшетау»\nРазработчик: ТОО «ПромПроект Астана»\nг. Астана, 2026 г.", 12
    )
    filler = (
        "Проектные решения соответствуют требованиям СН РК и СП РК, действующих на территории Республики Казахстан. "
        "Принятые технические решения обеспечивают безопасную эксплуатацию объекта, соблюдение норм промышленной "
        "безопасности, пожарной безопасности и охраны труда. Расчёты выполнены в соответствии с действующими "
        "нормативами, исходные данные приняты по заданию на проектирование и материалам изысканий. "
    )
    for title, body in TEO_CHAPTERS:
        pdf.new_page()
        pdf.text(title, 14, bold=True, gap=10)
        pdf.text(body)
        if title.startswith("4."):
            pdf.text("Таблица 4.1. Основное технологическое оборудование", 11, bold=True)
            rows = [("Наименование", "Кол-во", "Производитель", "Страна", "Цена, EUR")] + EQUIPMENT
            pdf.table(rows, [170, 45, 110, 75, 75])
        if title.startswith("9."):
            pdf.text("Таблица 9.1. Сводка капитальных затрат", 11, bold=True)
            pdf.table(
                [
                    ("Статья", "млн тенге"),
                    ("СМР", "3 950"),
                    ("Оборудование", "6 980"),
                    ("Инженерные сети", "910"),
                    ("Проектирование", "300"),
                    ("Прочие", "500"),
                    ("Итого", "12 640"),
                ],
                [300, 120],
            )
        for i in range(2):
            pdf.text(f"{title.split('.')[0]}.{i + 1}. " + filler * 4)
    while pdf.doc.page_count < 30:
        pdf.new_page()
        pdf.text("Приложение. Расчётные материалы", 12, bold=True)
        pdf.text(filler * 6)
    pdf.save(out)


# ---------- КП поставщиков ----------


def make_kp(out: Path, supplier: str, country: str, price: str, items: list[tuple[str, str, str]]) -> None:
    pdf = Pdf()
    pdf.new_page()
    pdf.text(f"{supplier}", 16, bold=True)
    pdf.text(
        f"КОММЕРЧЕСКОЕ ПРЕДЛОЖЕНИЕ № CP-2026-{sum(map(ord, supplier)) % 900 + 100}", 13, bold=True, gap=10
    )
    pdf.text(
        "Кому: ТОО «Агро Инвест Кокшетау»\nПредмет: комплектная мельница для сортового помола пшеницы 300 т/сут"
    )
    pdf.text(
        f"Страна производства: {country}. Условия поставки: DAP Кокшетау (Incoterms 2020). "
        "Срок действия предложения: 90 дней. Срок поставки: 9 месяцев с даты предоплаты. "
        "Условия оплаты: 30% предоплата, 60% по готовности к отгрузке, 10% после пусконаладки."
    )
    pdf.table([("Позиция", "Кол-во", "Цена за единицу, EUR")] + items, [260, 60, 140])
    pdf.text(f"Итого стоимость предложения: {price} EUR без НДС. Шеф-монтаж и пусконаладка включены.")
    pdf.save(out)


