# ---------- скан ТУ (jpg) ----------


def make_tu_scan(out: Path) -> None:
    from PIL import Image, ImageDraw, ImageFilter, ImageFont

    rnd = random.Random(42)
    img = Image.new("L", (1654, 2339), 248)  # A4 при 200 dpi
    draw = ImageDraw.Draw(img)
    title = ImageFont.truetype(FONT_BOLD, 44)
    body = ImageFont.truetype(FONT, 34)
    lines = [
        ("АО «Акмолинская распределительная электросетевая компания»", body),
        ("", body),
        ("ТЕХНИЧЕСКИЕ УСЛОВИЯ № ТУ-2026/0417", title),
        ("на подключение к электрическим сетям", title),
        ("", body),
        ("Выданы: ТОО «Агро Инвест Кокшетау»", body),
        ("Объект: мукомольный завод, г. Кокшетау, промзона", body),
        ("Разрешенная мощность: 2600 кВт", body),
        ("Категория надежности электроснабжения: II", body),
        ("Точка подключения: ПС 110/10 кВ «Кокшетау-Промышленная»,", body),
        ("ячейки 10 кВ № 7 и № 12", body),
        ("Напряжение в точке подключения: 10 кВ", body),
        ("Срок действия технических условий: 3 года", body),
        ("", body),
        ("Заказчику выполнить: строительство двух КЛ-10 кВ", body),
        ("протяженностью 2,1 км, установку КТП 2х1600 кВА.", body),
        ("", body),
        ("Главный инженер                                  подпись", body),
    ]
    y = 180
    for text, font in lines:
        draw.text((140, y), text, fill=rnd.randint(10, 40), font=font)
        y += 70 if font is body else 80
    img = img.rotate(0.8, fillcolor=248, resample=Image.Resampling.BICUBIC)
    px = img.load()
    for _ in range(25000):  # «шум сканера»
        x, yy = rnd.randrange(img.width), rnd.randrange(img.height)
        px[x, yy] = rnd.randint(150, 230)
    img.filter(ImageFilter.GaussianBlur(0.6)).save(out, "JPEG", quality=80)


def generate(target: Path = FILES_DIR) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    make_business_plan(target / "Бизнес-план_Мукомольный_завод.docx")
    make_teo(target / "ТЭО_мукомольный_завод_300тсут.pdf")
    make_finmodel(target / "Финмодель_мукомольный_завод.xlsx")
    make_kp(
        target / "КП_Buhler_мельничный_комплекс.pdf",
        "Bühler AG",
        "Швейцария",
        "5 520 000",
        [
            ("Вальцовый станок MDDK", "16", "115 000"),
            ("Рассев MPAV", "6", "186 700"),
            ("Ситовеечная машина MQRF", "4", "105 000"),
        ],
    )
    make_kp(
        target / "КП_Ocrim_мельничное_оборудование.pdf",
        "Ocrim S.p.A.",
        "Италия",
        "4 980 000",
        [
            ("Вальцовый станок RE", "16", "98 000"),
            ("Рассев PL", "6", "171 000"),
            ("Ситовеечная машина SV", "4", "92 000"),
        ],
    )
